svg.script:
(function () {
  function ready(f){ if(document.readyState!=='loading')f();
    else document.addEventListener('DOMContentLoaded',f); }
  ready(function () {
    var vids = Array.prototype.slice.call(document.querySelectorAll('video'));
    if (vids.length < 2) return;
    var master = vids[0];
    // Slave slaves to master's currentTime whenever drift > 0.15s
    master.addEventListener('timeupdate', function () {
      var t = master.currentTime;
      for (var i = 1; i < vids.length; i++) {
        var v = vids[i];
        if (Math.abs(v.currentTime - t) > 0.15) v.currentTime = t;
      }
    });
    // Master loops → resync all slaves to 0
    master.addEventListener('seeked', function () {
      if (master.currentTime < 0.1) {
        for (var i = 1; i < vids.length; i++) vids[i].currentTime = 0;
      }
    });
    // Pause-on-stall: if any video buffers, pause all until every one
    // is ready (readyState >= 3 = HAVE_FUTURE_DATA).
    function allReady(){ return vids.every(function(v){ return v.readyState >= 3; }); }
    function pauseAll(){ vids.forEach(function(v){ try{v.pause();}catch(e){} }); }
    function playAll(){ vids.forEach(function(v){ v.play().catch(function(){}); }); }
    vids.forEach(function (v) {
      v.addEventListener('waiting', pauseAll);
      v.addEventListener('canplay', function () {
        if (allReady()) playAll();
      });
    });
    // Best-effort start (some browsers won't autoplay without this nudge
    // when videos come in via foreignObject).
    if (allReady()) playAll();
  });
})();
